{
  "meta": {
    "name": "RecipeShare",
    "description": "A recipe sharing app where users can post recipes, comment on them, and premium users get access to weekly meal planning."
  },
  "entities": [
    {
      "name": "Recipe",
      "ownable": true,
      "fields": [
        {
          "name": "title",
          "type": "string",
          "required": true
        },
        {
          "name": "description",
          "type": "text"
        },
        {
          "name": "ingredients",
          "type": "text",
          "required": true
        },
        {
          "name": "steps",
          "type": "text",
          "required": true
        }
      ]
    },
    {
      "name": "Comment",
      "ownable": true,
      "fields": [
        {
          "name": "text",
          "type": "text",
          "required": true
        },
        {
          "name": "timestamp",
          "type": "datetime",
          "required": true
        }
      ],
      "relations": [
        {
          "name": "recipe",
          "kind": "manyToOne",
          "target": "Recipe",
          "required": true
        }
      ]
    },
    {
      "name": "MealPlan",
      "ownable": true,
      "fields": [
        {
          "name": "weekStartDate",
          "type": "date",
          "required": true
        }
      ],
      "relations": [
        {
          "name": "recipes",
          "kind": "manyToMany",
          "target": "Recipe"
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "user",
      "isDefault": true
    },
    {
      "name": "premiumUser"
    }
  ],
  "permissions": [
    {
      "role": "user",
      "entity": "Recipe",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "user",
      "entity": "Comment",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "premiumUser",
      "entity": "MealPlan",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own",
      "requiresPlan": "premium"
    }
  ],
  "pages": [
    {
      "name": "Recipes",
      "route": "/recipes",
      "type": "list",
      "entity": "Recipe",
      "access": [
        "user",
        "premiumUser"
      ]
    },
    {
      "name": "New Recipe",
      "route": "/recipes/new",
      "type": "form",
      "entity": "Recipe",
      "access": [
        "user",
        "premiumUser"
      ]
    },
    {
      "name": "Recipe Detail",
      "route": "/recipes/:id",
      "type": "detail",
      "entity": "Recipe",
      "access": [
        "user",
        "premiumUser"
      ]
    },
    {
      "name": "Meal Plan",
      "route": "/meal-plan",
      "type": "custom",
      "access": [
        "premiumUser"
      ],
      "requiresPlan": "premium"
    }
  ],
  "plans": [
    {
      "name": "free",
      "isDefault": true
    },
    {
      "name": "premium",
      "price": 10,
      "interval": "month",
      "features": [
        "meal planning"
      ]
    }
  ],
  "businessRules": [
    {
      "type": "plan_gate",
      "id": "premiumMealPlanGate",
      "requiresPlan": "premium",
      "gates": {
        "pages": [
          "Meal Plan"
        ],
        "features": [
          "meal planning"
        ]
      }
    },
    {
      "type": "ownership",
      "id": "recipeOwnership",
      "entity": "Recipe"
    },
    {
      "type": "ownership",
      "id": "commentOwnership",
      "entity": "Comment"
    },
    {
      "type": "ownership",
      "id": "mealPlanOwnership",
      "entity": "MealPlan"
    }
  ],
  "auth": {
    "strategy": "email_password",
    "requireAuth": true
  }
}
